id": "0B_Fq1xsSZuWIQm9JY2lpdGFYYVE", "rk": "0-PoC3tBGW765uBmXo56XnKw"}];

// State Variables
let currentPage = parseInt(localStorage.getItem('slamdunk_page') || '1', 10);
if (currentPage < 1 || currentPage > PAGES_DATA.length) currentPage = 1;

let viewMode = localStorage.getItem('slamdunk_view_mode') || 'double'; // 'single', 'double', 'scroll'
let readingDirection = localStorage.getItem('slamdunk_direction') || 'rtl'; // 'rtl' (우->좌 만화 원작), 'ltr' (좌->우)
let fitMode = localStorage.getItem('slamdunk_fit_mode') || 'height'; // 'height', 'width'
let isToolbarVisible = true;
let isDrawerOpen = false;

// DOM Elements
const header = document.getElementById('main-header');
const footer = document.getElementById('main-footer');
const viewport = document.getElementById('viewer-viewport');
const pageContainer = document.getElementById('page-container');
const pageSlider = document.getElementById('page-slider');
const pageInput = document.getElementById('page-input');
const totalCountSpan = document.getElementById('total-page-count');
const thumbDrawer = document.getElementById('thumb-drawer');
const drawerGrid = document.getElementById('drawer-grid');
const backdrop = document.getElementById('backdrop');
const spinner = document.getElementById('loading-spinner');
const toast = document.getElementById('toast');
const helpModal = document.getElementById('help-modal');

const btnModeSingle = document.getElementById('btn-mode-single');
const btnModeDouble = document.getElementById('btn-mode-double');
const btnModeScroll = document.getElementById('btn-mode-scroll');
const btnDirection = document.getElementById('btn-direction');
const directionLabel = document.getElementById('direction-label');
const btnFitToggle = document.getElementById('btn-fit-toggle');

// Build Image URLs with fallback options
function getImageUrl(id, rk, quality = 'high') {
  const sizeParam = quality === 'thumb' ? 'w300' : 'w1920';
  const rkParam = rk ? `&resourcekey=${rk}` : '';
  return `https://drive.google.com/thumbnail?id=${id}&sz=${sizeParam}${rkParam}`;
}

function getFallbackUrl(id, rk) {
  const rkParam = rk ? `?resourcekey=${rk}` : '';
  return `https://lh3.googleusercontent.com/d/${id}${rkParam}`;
}

function showToast(msg, duration = 1800) {
  toast.textContent = msg;
  toast.classList.add('show');
  clearTimeout(toast._timer);
  toast._timer = setTimeout(() => toast.classList.remove('show'), duration);
}

// Preload adjacent images
function preloadPage(pageNum) {
  if (pageNum >= 1 && pageNum <= PAGES_DATA.length) {
    const item = PAGES_DATA[pageNum - 1];
    const img = new Image();
    img.src = getImageUrl(item.id, item.rk);
  }
}

function preloadNearby() {
  if (viewMode === 'double') {
    preloadPage(currentPage + 2);
    preloadPage(currentPage + 3);
    preloadPage(currentPage - 2);
  } else {
    preloadPage(currentPage + 1);
    preloadPage(currentPage + 2);
    preloadPage(currentPage - 1);
  }
}

// Render Pages depending on viewMode
function render() {
  localStorage.setItem('slamdunk_page', currentPage);
  pageSlider.value = currentPage;
  pageInput.value = currentPage;

  // Update View Buttons
  btnModeSingle.classList.toggle('btn-active', viewMode === 'single');
  btnModeDouble.classList.toggle('btn-active', viewMode === 'double');
  btnModeScroll.classList.toggle('btn-active', viewMode === 'scroll');

  // Update Reading Direction UI
  btnDirection.style.display = viewMode === 'scroll' ? 'none' : 'inline-flex';
  directionLabel.textContent = readingDirection === 'rtl' ? '우→좌' : '좌→우';

  // Update viewport class
  viewport.className = viewMode === 'scroll' ? 'mode-scroll' : `fit-${fitMode}`;

  if (viewMode === 'scroll') {
    renderScrollMode();
  } else if (viewMode === 'single') {
    renderSingleMode();
  } else {
    renderDoubleMode();
  }

  updateThumbnailActiveState();
  preloadNearby();
}

function createPageImg(pageObj) {
  const img = document.createElement('img');
  img.className = 'manga-page';
  img.alt = `페이지 ${pageObj.page}`;
  img.src = getImageUrl(pageObj.id, pageObj.rk);
  img.onerror = function() {
    // Fallback to Google CDN format
    if (!this.dataset.fallbackTried) {
      this.dataset.fallbackTried = 'true';
      this.src = getFallbackUrl(pageObj.id, pageObj.rk);
    }
  };
  return img;
}

function renderSingleMode() {
  pageContainer.innerHTML = '';
  spinner.style.display = 'block';

  const pageObj = PAGES_DATA[currentPage - 1];
  const img = createPageImg(pageObj);
  img.onload = () => { spinner.style.display = 'none'; };
  img.onerror = () => { spinner.style.display = 'none'; };
  pageContainer.appendChild(img);
}

function renderDoubleMode() {
  pageContainer.innerHTML = '';
  spinner.style.display = 'block';

  // First page (Page 1) is typically the single solo cover!
  if (currentPage === 1) {
    const pageObj = PAGES_DATA[0];
    const img = createPageImg(pageObj);
    img.onload = () => { spinner.style.display = 'none'; };
    pageContainer.appendChild(img);
    return;
  }

  // Calculate paired pages (e.g. 2 & 3, 4 & 5, ...)
  let p1Num = currentPage % 2 === 0 ? currentPage : currentPage - 1;
  let p2Num = p1Num + 1;

  const p1Obj = PAGES_DATA[p1Num - 1];
  const p2Obj = p2Num <= PAGES_DATA.length ? PAGES_DATA[p2Num - 1] : null;

  let loadedCount = 0;
  const totalToLoad = p2Obj ? 2 : 1;
  const onLoadCheck = () => {
    loadedCount++;
    if (loadedCount >= totalToLoad) spinner.style.display = 'none';
  };

  const img1 = createPageImg(p1Obj);
  img1.onload = onLoadCheck;

  let img2 = null;
  if (p2Obj) {
    img2 = createPageImg(p2Obj);
    img2.onload = onLoadCheck;
  }

  // Reading Direction in Manga:
  // In RTL (우->좌), the earlier page (e.g. Page 2) goes on the RIGHT, and the later page (Page 3) goes on the LEFT!
  // In LTR (좌->우), earlier page on LEFT, later page on RIGHT.
  if (readingDirection === 'rtl') {
    if (img2) pageContainer.appendChild(img2); // Page 3 on left
    pageContainer.appendChild(img1);          // Page 2 on right
  } else {
    pageContainer.appendChild(img1);          // Page 2 on left
    if (img2) pageContainer.appendChild(img2); // Page 3 on right
  }
}

let scrollModeBuilt = false;
function renderScrollMode() {
  if (scrollModeBuilt) {
    scrollToCurrentPageInScrollMode();
    return;
  }

  pageContainer.innerHTML = '';
  spinner.style.display = 'block';

  // Fragment to build all pages
  const fragment = document.createDocumentFragment();
  PAGES_DATA.forEach((p, idx) => {
    const img = createPageImg(p);
    img.dataset.page = p.page;
    img.loading = idx < 5 ? 'eager' : 'lazy';
    fragment.appendChild(img);
  });

  pageContainer.appendChild(fragment);
  scrollModeBuilt = true;
  spinner.style.display = 'none';

  // Observe scrolling to update currentPage
  setupScrollObserver();
  setTimeout(scrollToCurrentPageInScrollMode, 100);
}

function scrollToCurrentPageInScrollMode() {
  const targetImg = pageContainer.querySelector(`img[data-page="${currentPage}"]`);
  if (targetImg) {
    targetImg.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
}

let scrollObserver = null;
function setupScrollObserver() {
  if (scrollObserver) scrollObserver.disconnect();
  scrollObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const p = parseInt(entry.target.dataset.page, 10);
        if (p && viewMode === 'scroll') {
          currentPage = p;
          pageSlider.value = p;
          pageInput.value = p;
          localStorage.setItem('slamdunk_page', p);
          updateThumbnailActiveState();
        }
      }
    });
  }, { root: viewport, threshold: 0.5 });

  pageContainer.querySelectorAll('img').forEach(img => scrollObserver.observe(img));
}

// Navigation functions
function goToPage(page) {
  if (page < 1) page = 1;
  if (page > PAGES_DATA.length) page = PAGES_DATA.length;
  currentPage = page;
  render();
}

function nextPage() {
  if (viewMode === 'double') {
    if (currentPage === 1) {
      goToPage(2);
    } else {
      goToPage(currentPage + 2);
    }
  } else {
    goToPage(currentPage + 1);
  }
}

function prevPage() {
  if (viewMode === 'double') {
    if (currentPage <= 3) {
      goToPage(1);
    } else {
      goToPage(currentPage - 2);
    }
  } else {
    goToPage(currentPage - 1);
  }
}

// Toolbar visibility toggle
function toggleToolbars(forceState) {
  isToolbarVisible = forceState !== undefined ? forceState : !isToolbarVisible;
  header.classList.toggle('hidden', !isToolbarVisible);
  footer.classList.toggle('hidden', !isToolbarVisible);
}

// Build Thumbnail Drawer
function initThumbnails() {
  totalCountSpan.textContent = PAGES_DATA.length;
  pageSlider.max = PAGES_DATA.length;
  pageInput.max = PAGES_DATA.length;

  const fragment = document.createDocumentFragment();
  PAGES_DATA.forEach(p => {
    const card = document.createElement('div');
    card.className = 'thumb-card';
    card.id = `thumb-page-${p.page}`;

    const img = document.createElement('img');
    img.className = 'thumb-img';
    img.alt = `p.${p.page}`;
    img.loading = 'lazy';
    img.src = getImageUrl(p.id, p.rk, 'thumb');

    const label = document.createElement('div');
    label.className = 'thumb-label';
    label.textContent = `${p.page} 쪽`;

    card.appendChild(img);
    card.appendChild(label);

    card.addEventListener('click', () => {
      goToPage(p.page);
      closeDrawer();
    });

    fragment.appendChild(card);
  });
  drawerGrid.appendChild(fragment);
}

function updateThumbnailActiveState() {
  const prevActive = drawerGrid.querySelector('.thumb-card.active');
  if (prevActive) prevActive.classList.remove('active');

  const currentCard = document.getElementById(`thumb-page-${currentPage}`);
  if (currentCard) {
    currentCard.classList.add('active');
    if (isDrawerOpen) {
      currentCard.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }
}

function openDrawer() {
  isDrawerOpen = true;
  thumbDrawer.classList.add('open');
  backdrop.classList.add('show');
  updateThumbnailActiveState();
}

function closeDrawer() {
  isDrawerOpen = false;
  thumbDrawer.classList.remove('open');
  backdrop.classList.remove('show');
}

// Fullscreen Toggle
function toggleFullscreen() {
  const fsIconEnter = document.getElementById('fs-icon-enter');
  const fsIconExit = document.getElementById('fs-icon-exit');

  if (!document.fullscreenElement) {
    document.documentElement.requestFullscreen().then(() => {
      fsIconEnter.style.display = 'none';
      fsIconExit.style.display = 'block';
      showToast('전체화면 모드 시작');
    }).catch(err => console.log(err));
  } else {
    if (document.exitFullscreen) {
      document.exitFullscreen().then(() => {
        fsIconEnter.style.display = 'block';
        fsIconExit.style.display = 'none';
      });
    }
  }
}

// Event Listeners Setup
function setupEvents() {
  // Page turning zones (respects reading direction in double/single mode!)
  document.getElementById('zone-prev').addEventListener('click', (e) => {
    e.stopPropagation();
    if (readingDirection === 'rtl') nextPage(); else prevPage();
  });

  document.getElementById('zone-next').addEventListener('click', (e) => {
    e.stopPropagation();
    if (readingDirection === 'rtl') prevPage(); else nextPage();
  });

  document.getElementById('zone-center').addEventListener('click', () => {
    toggleToolbars();
  });

  // Footer Navigation Buttons
  document.getElementById('btn-prev').addEventListener('click', prevPage);
  document.getElementById('btn-next').addEventListener('click', nextPage);
  document.getElementById('btn-first').addEventListener('click', () => goToPage(1));
  document.getElementById('btn-last').addEventListener('click', () => goToPage(PAGES_DATA.length));

  // Slider & Input Change
  pageSlider.addEventListener('input', (e) => {
    goToPage(parseInt(e.target.value, 10));
  });

  pageInput.addEventListener('change', (e) => {
    let p = parseInt(e.target.value, 10);
    if (isNaN(p)) p = currentPage;
    goToPage(p);
  });

  // View Mode Buttons
  btnModeSingle.addEventListener('click', () => {
    viewMode = 'single';
    scrollModeBuilt = false;
    localStorage.setItem('slamdunk_view_mode', viewMode);
    render();
    showToast('단면 보기 모드');
  });

  btnModeDouble.addEventListener('click', () => {
    viewMode = 'double';
    scrollModeBuilt = false;
    localStorage.setItem('slamdunk_view_mode', viewMode);
    render();
    showToast('양면 펼쳐보기 모드');
  });

  btnModeScroll.addEventListener('click', () => {
    viewMode = 'scroll';
    localStorage.setItem('slamdunk_view_mode', viewMode);
    render();
    showToast('연속 스크롤 모드');
  });

  // Direction Toggle
  btnDirection.addEventListener('click', () => {
    readingDirection = readingDirection === 'rtl' ? 'ltr' : 'rtl';
    localStorage.setItem('slamdunk_direction', readingDirection);
    render();
    showToast(readingDirection === 'rtl' ? '우→좌 읽기 (만화 원작 방향)' : '좌→우 읽기 (일반 방향)');
  });

  // Fit Mode Toggle
  btnFitToggle.addEventListener('click', () => {
    if (viewMode === 'scroll') return;
    fitMode = fitMode === 'height' ? 'width' : 'height';
    localStorage.setItem('slamdunk_fit_mode', fitMode);
    viewport.className = `fit-${fitMode}`;
    showToast(fitMode === 'height' ? '화면 높이에 맞춤' : '화면 너비에 맞춤');
  });

  // Drawer open/close
  document.getElementById('btn-toggle-drawer').addEventListener('click', openDrawer);
  document.getElementById('btn-close-drawer').addEventListener('click', closeDrawer);
  backdrop.addEventListener('click', () => {
    closeDrawer();
    helpModal.classList.remove('open');
  });

  // Help Modal
  document.getElementById('btn-help').addEventListener('click', () => {
    helpModal.classList.add('open');
    backdrop.classList.add('show');
  });

  document.getElementById('btn-close-modal').addEventListener('click', () => {
    helpModal.classList.remove('open');
    if (!isDrawerOpen) backdrop.classList.remove('show');
  });

  // Fullscreen
  document.getElementById('btn-fullscreen').addEventListener('click', toggleFullscreen);

  // Keyboard Shortcuts
  window.addEventListener('keydown', (e) => {
    if (helpModal.classList.contains('open') && e.key === 'Escape') {
      helpModal.classList.remove('open');
      backdrop.classList.remove('show');
      return;
    }

    if (isDrawerOpen && e.key === 'Escape') {
      closeDrawer();
      return;
    }

    if (document.activeElement === pageInput) return;

    switch (e.key) {
      case 'ArrowRight':
      case 'd':
      case 'D':
        if (readingDirection === 'rtl') prevPage(); else nextPage();
        break;
      case 'ArrowLeft':
      case 'a':
      case 'A':
        if (readingDirection === 'rtl') nextPage(); else prevPage();
        break;
      case ' ': // Spacebar
        if (e.shiftKey) prevPage(); else nextPage();
        e.preventDefault();
        break;
      case '1':
        btnModeSingle.click();
        break;
      case '2':
        btnModeDouble.click();
        break;
      case '3':
        btnModeScroll.click();
        break;
      case 'f':
      case 'F':
        toggleFullscreen();
        break;
      case 't':
      case 'T':
      case 'm':
      case 'M':
        if (isDrawerOpen) closeDrawer(); else openDrawer();
        break;
      case 'h':
      case 'H':
        toggleToolbars();
        break;
      case 'Home':
        goToPage(1);
        break;
      case 'End':
        goToPage(PAGES_DATA.length);
        break;
      case '?':
        helpModal.classList.toggle('open');
        backdrop.classList.toggle('show');
        break;
    }
  });

  // Swipe Gestures for Mobile
  let touchStartX = 0;
  let touchStartY = 0;
  viewport.addEventListener('touchstart', (e) => {
    if (e.touches.length === 1) {
      touchStartX = e.touches[0].clientX;
      touchStartY = e.touches[0].clientY;
    }
  }, { passive: true });

  viewport.addEventListener('touchend', (e) => {
    if (viewMode === 'scroll') return;
    if (e.changedTouches.length === 1) {
      const deltaX = e.changedTouches[0].clientX - touchStartX;
      const deltaY = e.changedTouches[0].clientY - touchStartY;
      if (Math.abs(deltaX) > 50 && Math.abs(deltaY) < 60) {
        if (deltaX < 0) {
          // Swiped left
          if (readingDirection === 'rtl') prevPage(); else nextPage();
        } else {
          // Swiped right
          if (readingDirection === 'rtl') nextPage(); else prevPage();
        }
      }
    }
  }, { passive: true });
}

// Initialization
window.addEventListener('DOMContentLoaded', () => {
  initThumbnails();
  setupEvents();
  render();

  if (currentPage > 1) {
    showToast(`${currentPage}쪽부터 이어보기 중입니다`);
  }
});
